INSERT INTO letters (id, bridge_id, display_nickname, body, theme, is_seed, status) VALUES
  ('00000000-0000-4000-8000-000000000201', 'sillim', '밤 산책자', '지금까지 온 길만큼 앞으로의 길도 천천히 걸어가면 돼요.', 1, true, 'published'),
  ('00000000-0000-4000-8000-000000000202', 'sillim', '별을 보는 사람', '오늘도 충분히 잘하고 있어요. 잠깐 쉬어가도 괜찮아요.', 2, true, 'published'),
  ('00000000-0000-4000-8000-000000000205', 'sillim', '달빛 한 조각', '조금 느린 날도 괜찮아요. 당신의 속도로 걸어가면 돼요.', 3, true, 'published'),
  ('00000000-0000-4000-8000-000000000206', 'sillim', '동네 산책자', '오늘 해낸 작은 일 하나도 충분히 자랑스러워요.', 4, true, 'published'),
  ('00000000-0000-4000-8000-000000000207', 'sillim', '조용한 응원', '막막한 순간에도 당신 곁에서 응원하는 마음이 있어요.', 1, true, 'published'),
  ('00000000-0000-4000-8000-000000000203', 'bongnim', '따뜻한 이웃', '당신이 건넨 작은 친절이 누군가의 하루를 밝히고 있어요.', 3, true, 'published'),
  ('00000000-0000-4000-8000-000000000208', 'bongnim', '골목의 불빛', '문을 잡아준 손길처럼 작은 배려는 오래 마음에 남아요.', 1, true, 'published'),
  ('00000000-0000-4000-8000-000000000209', 'bongnim', '옆집 이웃', '오늘 받은 다정함을 내일 또 다른 사람에게 건네고 싶어요.', 2, true, 'published'),
  ('00000000-0000-4000-8000-000000000210', 'bongnim', '퇴근길 친구', '먼저 건넨 인사 한마디가 누군가에겐 큰 위로였을 거예요.', 4, true, 'published'),
  ('00000000-0000-4000-8000-000000000211', 'bongnim', '작은 별', '서로의 하루를 조금씩 밝혀주는 이웃이 있어 참 좋아요.', 3, true, 'published'),
  ('00000000-0000-4000-8000-000000000204', 'sillim2', '새벽의 친구', '오늘의 당신에게 고생했다고 말해주고 싶어요.', 4, true, 'published'),
  ('00000000-0000-4000-8000-000000000212', 'sillim2', '내일의 나', '완벽하지 않아도 오늘을 지나온 나에게 고맙다고 말해요.', 1, true, 'published'),
  ('00000000-0000-4000-8000-000000000213', 'sillim2', '밤하늘 아래', '힘든 마음을 잠시 내려놓고 깊게 숨 쉬어도 괜찮아요.', 2, true, 'published'),
  ('00000000-0000-4000-8000-000000000214', 'sillim2', '느린 걸음', '오늘 못한 일보다 오늘 버텨낸 순간을 먼저 떠올려요.', 3, true, 'published'),
  ('00000000-0000-4000-8000-000000000215', 'sillim2', '도림천 산책자', '내일의 나에게 조금 더 가벼운 아침이 오기를 바라요.', 4, true, 'published')
